class Solution {
public:
    int minimumCost(vector<int>& cost) {
        int freq[101] = {0};
        for (int c : cost) freq[c]++;
        int total = 0;
        int pos = 0;
        for (int c = 100; c >= 1; c--) {
            while (freq[c] > 0) {
                if (pos % 3 != 2) total += c;
                pos++;
                freq[c]--;
            }
        }
        return total;
    }
};
